function renderStats(){const arr=[...data.entries].sort((a,b)=>a.date.localeCompare(b.date));const avg=k=>arr.length?(arr.reduce((s,e)=>s+Number(e[k]||0),0)/arr.length).toFixed(1):'—';$('statsCards').innerHTML=[['Días registrados',arr.length],['Inflamación media',avg('handSwelling')],['Cansancio medio',avg('fatigue')],['Entrenamientos',arr.reduce((s,e)=>s+(e.trainings?.length||0),0)]].map(([l,v])=>`<article class="stat-card"><span>${l}</span><strong>${v}</strong></article>`).join('');drawChart(arr)}
function drawChart(arr){const c=$('statsChart'),ctx=c.getContext('2d'),dpr=devicePixelRatio||1,w=c.clientWidth||700,h=220;c.width=w*dpr;c.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.strokeStyle='#dfe8e8';for(let i=0;i<=5;i++){const y=20+i*(h-40)/5;ctx.beginPath();ctx.moveTo(28,y);ctx.lineTo(w-8,y);ctx.stroke()}if(!arr.length){ctx.fillStyle='#74868b';ctx.fillText('Sin datos',w/2-20,h/2);return}for(const [k,col] of [['handSwelling','#0f766e'],['fatigue','#d99a24']]){ctx.strokeStyle=col;ctx.lineWidth=3;ctx.beginPath();arr.forEach((e,i)=>{const x=30+i*(w-44)/Math.max(1,arr.length-1),y=h-20-(Number(e[k]||0)/10)*(h-40);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}}
const configMeta={dailySupplements:{title:'Suplemento diario'},sportSupplements:{title:'Suplemento deportivo'},medications:{title:'Medicación'},trainingTypes:{title:'Tipo de entrenamiento'}};
function renderSettings(){for(const key of ['dailySupplements','sportSupplements','medications','trainingTypes']){const list=$(key+'List'),arr=data[key]||[];list.innerHTML=arr.sort((a,b)=>(a.order||0)-(b.order||0)).map(x=>`<div class="config-item"><span class="config-grip">⋮⋮</span><div class="config-main"><strong>${esc(x.name)}</strong><small>${key==='trainingTypes'?esc(x.kind||'otro'):`${x.dose??0} ${esc(x.unit||'')} ${x.defaultTaken?'· marcado por defecto':''} ${x.composition?`· ${esc(x.composition)}`:''}`}</small></div><button class="config-toggle ${x.enabled!==false?'on':''}" data-toggle="${key}" data-id="${x.id}"></button><button class="icon-mini" data-edit="${key}" data-id="${x.id}">✎</button><button class="icon-mini danger-text" data-del="${key}" data-id="${x.id}">×</button></div>`).join('')||'<div class="empty-config">Sin elementos.</div>'}bindConfigButtons()}
